{
  "name": "setprototypeof",
  "version": "1.0.0",
  "description": "A cross-platform way to set the prototype of an object at runtime.",
  "keywords": [
    "prototype",
    "setPrototypeOf",
    "proto",
    "polyfill",
    "cross-platform"
  ],
  "license": "MIT",
  "main": "index.js",
  "files": [
    "index.js"
  ],
